export const seoLandingPages = [...destinationPages, ...stayPages, ...groupPages, ...experienceLandingPages, ...amenityPages]

export function getSeoPagesByGroup(group: SeoPageGroup) {
  return seoLandingPages.filter((page) => page.group === group)
}

export function getSeoPage(group: SeoPageGroup, slug: string) {
  return seoLandingPages.find((page) => page.group === group && page.slug === slug)
}

export function getSeoPageByPath(path: string) {
  return seoLandingPages.find((page) => page.path === path)
}

export function getRelatedSeoPages(page: SeoLandingPage) {
  return page.relatedPaths
    .map((path) => getSeoPageByPath(path))
    .filter((item): item is SeoLandingPage => Boolean(item))
}

export function getSeoPathGroup(path: string) {
  if (path.startsWith("/destinations")) return "destinations"
  if (path.startsWith("/stays")) return "stays"
  if (path.startsWith("/groups")) return "groups"
  if (path.startsWith("/amenities")) return "amenities"
  return "experiences"
}
